const valueOrNull = (value) => {
  if (value === undefined || value === null) return null;
  if (typeof value === 'string' && value.trim() === '') return null;
  return value;
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return value === 1;

  if (typeof value === 'string') {
    return ['true', '1', 'yes', 'on'].includes(
      value.trim().toLowerCase()
    );
  }

  return false;
};

const toNonNegativeNumberOrNull = (value) => {
  if (value === undefined || value === null || value === '') return null;

  const number = Number(value);

  if (
    !Number.isFinite(number) ||
    !Number.isInteger(number) ||
    number < 0
  ) {
    return null;
  }

  return number;
};

const generateUuid = () => {
  if (globalThis.crypto?.randomUUID) {
    return globalThis.crypto.randomUUID();
  }

  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(
    /[xy]/g,
    (character) => {
      const random = Math.floor(Math.random() * 16);
      const value =
        character === 'x'
          ? random
          : (random & 0x3) | 0x8;

      return value.toString(16);
    }
  );
};

return $input.all().map((item, index) => {
  const row = item.json;
  const timestamp = new Date().toISOString();

  return {
    json: {
      lead_id: generateUuid(),

      source: {
        type: 'csv',
        external_id: valueOrNull(row.external_id),
        received_at: timestamp
      },

      contact: {
        name: valueOrNull(row.name),
        phone_raw: valueOrNull(row.mobile),
        phone_normalized: null,
        email_raw: valueOrNull(row.email),
        email_normalized: null,
        consent: toBoolean(row.consent)
      },

      business: {
        company_name: valueOrNull(row.company_name),
        service_interest: valueOrNull(row.service_interest),
        country: valueOrNull(row.country),
        industry: valueOrNull(row.industry),
        company_size: toNonNegativeNumberOrNull(row.company_size),

        // Internal system-controlled field.
        strategic_account: false
      },

      request: {
        message: valueOrNull(row.message),
        urgency: 'unknown'
      },

      processing: {
        status: 'processing',
        retry_count: 0,
        last_error: null,
        updated_at: timestamp,
        current_workflow: 'WF01_csv_import',
        next_workflow: 'WF02_validation_identity'
      },

      metadata: {
        schema_version: '1.0',
        workflow_version: '1.0'
      }
    },

    pairedItem: {
      item: index
    }
  };
});

return [{
  json: {
    status: 'completed',
    source: 'csv',
    processed_at: new Date().toISOString()
  }
}];
